import * as indianPropertyGuide from '../data/indian-property-guide.mjs';
import fs from 'node:fs/promises';
import path from 'node:path';
import sharp from 'sharp';
import services from '../data/services.mjs';
import guides from '../data/guides.mjs';
import {listingCollection} from './collections.mjs';
import {assertPublishable,canPublish} from './policy.mjs';
import {buildExpansion,loadAgents} from './expansion.mjs';
import {agentShowcase} from './agents-ui.mjs';
import {buildInternational} from './international-buyers.mjs';
import {articles as internationalArticles} from '../data/international-buyers.mjs';
import communityList from '../data/communities.mjs';
import {catalogProjects} from './catalog.mjs';
const business=JSON.parse(await fs.readFile('data/business.json','utf8'));
const projects=await Promise.all((await fs.readdir('data/projects')).filter(f=>f.endsWith('.json')).map(async f=>JSON.parse(await fs.readFile('data/projects/'+f,'utf8'))));
const projectOrder=['park-field','elie-saab','seagate','orania','lime-gardens','greencrest','hillsedge','fior-1'];
const rank=s=>{const i=projectOrder.indexOf(s);return i<0?999:i;};
projects.sort((a,b)=>rank(a.slug)-rank(b.slug));
projects.push(...await catalogProjects(projects));
const assignments=JSON.parse(await fs.readFile('data/assignments.json','utf8').catch(()=>'{}')).assignments||{};
for(const p of projects)if(assignments[p.slug])p.agent=assignments[p.slug];
const agentsBySlug=Object.fromEntries((await loadAgents()).filter(a=>a.status==='published').map(a=>[a.slug,a]));
const projectTitle=p=>{for(const t of [p.name+', '+p.community+' | Al Basel',p.name+' | Al Basel'])if(t.length<60)return t;return p.name.slice(0,44)+' | Al Basel';};
const devSlug=p=>({emaar:'emaar',deyaar:'deyaar',nakheel:'nakheel'})[(p.developer||'').toLowerCase()]||'emaar';
const properties=await Promise.all((await fs.readdir('data/properties')).filter(f=>f.endsWith('.json')).map(async f=>JSON.parse(await fs.readFile('data/properties/'+f,'utf8'))));
properties.forEach(p=>assertPublishable(p,business));
const published=properties.filter(p=>canPublish(p,business));
const outputRoot=path.resolve('dist');
if(outputRoot!==path.join(process.cwd(),'dist'))throw Error('Unexpected output directory');
await fs.rm(outputRoot,{recursive:true,force:true});
await fs.mkdir('dist',{recursive:true});
await fs.cp('public','dist',{recursive:true});
const pages=[];
const verificationHead=`<meta name="google-site-verification" content="xVRfhVYTXz15yJv0nxmQGVBLnZwEf_Wr5l2AriFIrRk" />
<meta name="prezlo-verified" content="c1578d9d49578ea426c6589aa406f0f5" />
<script src="https://prezlo.io/track.js" data-site="90af6741-8f57-4712-ae4a-50d92f1a4038" async></script>`;
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const slug=s=>s.toLowerCase().replaceAll('&','and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const wa=(subject='Dubai property')=>'https://wa.me/'+business.whatsapp+'?text='+encodeURIComponent('Hi, I am from your website. I would like to enquire about '+subject+'.');
const icon=(name)=>{const p={arrow:'<path d="M7 17 17 7M7 7h10v10"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',home:'<path d="m3 10 9-7 9 7v11H3zM9 21v-8h6v8"/>',building:'<path d="M4 21V5h10v16M14 10h6v11M8 9h2M8 13h2M8 17h2"/>',key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-4-4 3-3m-6 0 3-3"/>',chat:'<path d="M21 11.5a9 9 0 0 1-13.5 8L3 21l1.5-4.5A9 9 0 1 1 21 11.5Z"/><path d="M8 7c0 5 4 9 9 9"/>'};return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.arrow}</svg>`;};
const link=(url,label,cls='')=>`<a href="${url}"${cls?` class="${cls}"`:''}>${label}</a>`;
const bookButton=(subject='Dubai property')=>`<button type="button" class="button primary booking-button" data-lead-open data-lead-source="Book with Al Basel" data-lead-subject="${esc(subject)}"><img src="/assets/al-basel-booking.webp" width="28" height="28" alt=""><span>Book with Al Basel</span></button>`;
const dimensions={};
for(const dir of ['','projects/','communities/'])for(const file of await fs.readdir('public/assets/'+dir).catch(()=>[]))if(/\.(webp|png|jpg)$/.test(file)){const m=await sharp('public/assets/'+dir+file).metadata();dimensions[dir+file]=[m.width,m.height];}
const image=(name,alt,cls='',eager=false)=>`<img src="/assets/${name}" width="${dimensions[name]?.[0]||1500}" height="${dimensions[name]?.[1]||790}" alt="${esc(alt)}" ${cls?`class="${cls}"`:''} ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const header=(current)=>`<a class="skip-link" href="#main">Skip to content</a><header class="site-header wrap"><a class="brand" href="/" aria-label="Al Basel Real Estate home"><img src="/assets/logo.webp" width="420" height="115" alt="Al Basel Real Estate Brokers"></a><nav class="main-nav" aria-label="Main navigation">${[['/','Home'],['/buy/','Buy'],['/rent/','Rent'],['/projects/','Projects'],['/communities/','Communities'],['/developers/','Developers'],['/international-buyers/','International buyers'],['/about/','About us']].map(([u,t])=>link(u,t,current===u?'active':'')).join('')}</nav><div class="header-contact">${link('tel:'+business.phoneLink,business.phone)}${bookButton()}</div><button class="menu-toggle" data-menu aria-expanded="false" aria-label="Toggle navigation">☰</button></header>`;
const footer=(current)=>`<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand"><img src="/assets/logo.webp" width="420" height="115" alt="Al Basel Real Estate Brokers"><p>Property advice with a personal perspective. A member of ${esc(business.parentOrganization)}.</p></div><div class="footer-column"><h3>Explore</h3>${[['/buy/','Buy a property'],['/rent/','Rent a property'],['/projects/','Explore projects'],['/developers/','Our developers'],['/communities/','Communities'],['/international-buyers/','International buyers'],['/guides/','Property guides']].map(x=>link(...x)).join('')}</div><div class="footer-column"><h3>Al Basel</h3>${[['/about/','Our story'],['/team/','Our team'],['/awards/','Awards'],['/al-basel-group/','Al Basel Group'],['/verification/','Licence & verification'],['/how-we-work/','How we work'],['/resources/indian-property-ownership-nri-uae/','Indian property guide for UAE residents'],['/ai-search-trust/','Trust in AI search']].map(x=>link(...x)).join('')}</div><div class="footer-column"><h3>Come and say hello</h3><address>${esc(business.address)}</address>${link('tel:'+business.phoneLink,business.phone)}${link('mailto:'+business.email,business.email)}${link('/contact/','Contact & directions ↗')}</div></div><div class="footer-bottom"><span>© 2026 ${business.name}. All rights reserved.</span><div>${link('/privacy/','Privacy policy')}${link('/verification/','Brokerage ORN: '+(business.orn||'pending'))}</div></div></div></footer><nav class="mobile-nav" aria-label="Mobile navigation">${[['/','Home','home'],['/buy/','Buy','building'],['/rent/','Rent','key'],['/off-plan/','Off-plan','building'],[wa(),'WhatsApp','chat']].map(([u,t,i])=>link(u,icon(i)+t,current===u?'active':'')).join('')}</nav>`;
const cta=(heading='Your next chapter starts with a conversation.')=>`<section class="wrap"><div class="cta"><div><div class="eyebrow">LET’S FIND YOUR PLACE</div><h2>${heading}</h2><p>Tell us what matters to you. We’ll help you understand the options and take the next step.</p></div><div class="cta-actions">${bookButton()}${link('/contact/','Get in touch ↗','button outline')}</div></div></section>`;
const crumb=(parts)=>`<nav class="breadcrumb" aria-label="Breadcrumb">${link('/','Home')}${parts.map(([u,t])=>`<span aria-hidden="true">/</span>${u?link(u,esc(t)):`<span aria-current="page">${esc(t)}</span>`}`).join('')}</nav>`;
const intro=(tag,title,description)=>`<div class="page-intro"><div class="eyebrow">${esc(tag)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>`;
const sidebar=(subject)=>`<aside class="sidebar"><div class="eyebrow">PERSONAL PROPERTY ADVICE</div><h2>Let’s talk about ${esc(subject)}.</h2><p>Tell us your budget, preferred location and timeframe. We’ll confirm the details that matter to your enquiry.</p>${bookButton(subject)}${link('tel:'+business.phoneLink,'Call '+business.phone,'button outline')}<small>Office: ${esc(business.address)}<br>Brokerage ORN: ${business.orn||'pending'}</small></aside>`;
const agentSidebar=(p,a)=>`<aside class="sidebar"><div class="eyebrow">YOUR AGENT FOR ${esc(p.name.toUpperCase())}</div><h2>${esc(a.name)}</h2><p>${esc(a.title)} · BRN ${esc(a.brn)}</p><div class="agent-actions stacked"><button type="button" class="button primary" data-lead-open data-lead-source="Project page agent: ${esc(a.name)}" data-lead-subject="${esc(p.name+' (agent: '+a.name+')')}" data-lead-whatsapp="${esc(a.whatsapp)}" data-lead-tel="${esc(a.phoneLink)}" data-lead-tel-display="${esc(a.phone)}">Contact ${esc(a.name.split(' ')[0])} ${icon('chat')}</button>${link('tel:'+a.phoneLink,'Call '+esc(a.phone),'button outline')}${link('/agents/'+a.slug+'/','View '+esc(a.name.split(' ')[0])+'’s profile ↗','text-link')}</div><small>Brokerage licence ${esc(business.licence.number)}</small></aside>`;
const galleryHtml=(p)=>{
 const shots=[{src:'/assets/'+p.image,w:dimensions[p.image]?.[0]||1400,h:dimensions[p.image]?.[1]||788},...(p.gallery||[]).map(g=>({src:'/assets/'+g.file,w:g.w,h:g.h}))];
 if(shots.length<2)return `<button class="gallery-button" data-gallery aria-label="View ${esc(p.name)} project image">${image(p.image,p.name+' project image in '+p.community,'detail-hero',true)}<span>Expand image ↗</span></button><dialog id="image-dialog"><button type="button" aria-label="Close image">Close ×</button>${image(p.image,p.name+' project image')}</dialog>`;
 const alt=i=>esc(p.name+(i===0?' in '+p.community+', Dubai':' photo '+(i+1)));
 const thumbs=shots.slice(1,5);
 return `<div class="pgallery" data-pgallery><button type="button" class="pg-main" data-pg-open="0" aria-label="Open ${esc(p.name)} gallery, ${shots.length} photos"><img src="${shots[0].src}" width="${shots[0].w}" height="${shots[0].h}" alt="${alt(0)}" fetchpriority="high" decoding="async"></button><div class="pg-thumbs">${thumbs.map((t,i)=>`<button type="button" data-pg-open="${i+1}" aria-label="Open photo ${i+2} of ${shots.length}"><img src="${t.src}" width="${t.w}" height="${t.h}" alt="${alt(i+1)}" loading="lazy" decoding="async">${i===thumbs.length-1&&shots.length>5?`<span class="pg-more">+${shots.length-5} photos</span>`:''}</button>`).join('')}</div><span class="pg-count">${shots.length} photos · Developer images, may be renderings</span><dialog class="pg-lightbox" aria-label="${esc(p.name)} photo gallery"><button type="button" class="pg-close" aria-label="Close gallery">×</button><button type="button" class="pg-prev" aria-label="Previous photo">‹</button><img data-pg-img src="${shots[0].src}" width="${shots[0].w}" height="${shots[0].h}" alt="${alt(0)}"><button type="button" class="pg-next" aria-label="Next photo">›</button><p class="pg-counter" aria-live="polite"></p></dialog><script type="application/json" data-pg-list>${JSON.stringify(shots.map((x,i)=>({...x,alt:p.name+' photo '+(i+1)}))).replaceAll('<','\\u003c')}</script></div>`;
};
const card=(p)=>`<article class="project-card" data-project data-type="${p.type}" data-location="${esc(p.community)}"><a class="card-image" href="/projects/${p.slug}/">${image(p.image.replace('.webp','-card.webp'),p.name+' in '+p.community)}<span class="card-tag">${p.tag}</span><span class="card-arrow">↗</span></a><div class="card-info"><div class="card-top"><h3>${link('/projects/'+p.slug+'/',p.name)}</h3><span class="developer">${p.developer}</span></div><p class="location">⌖ &nbsp;${p.community}, Dubai</p><div class="card-details">${p.bedrooms}</div><div class="card-bottom"><span>Enquire for current details</span>${link(wa(p.name),icon('chat')+' WhatsApp')}</div></div></article>`;
const projectGrid=(items=projects)=>`<div class="project-grid">${items.map(card).join('')}</div>`;
const projectNotice='<div class="project-disclaimer">Project backgrounds from brokerage and developer sources. Images may be renderings. Confirm current prices, availability and status with us.</div>';
const search=()=>`<form class="search-panel" data-search action="/projects/" method="get"><div class="search-field"><label for="purpose">I’m looking to</label><select id="purpose" name="purpose"><option value="buy">Buy a property</option><option value="rent">Rent a property</option><option value="off-plan">Explore off-plan</option></select></div><div class="search-field"><label for="location">Preferred location</label><select id="location" name="location"><option value="">All Dubai communities</option>${[...new Set(projects.map(p=>p.community))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="search-field"><label for="type">Property type</label><select id="type" name="type"><option value="">All property types</option>${['Apartment','Villa','Townhouse'].map(t=>`<option>${t}</option>`).join('')}</select></div><button class="button primary" type="submit">${icon('search')} <span class="search-label-desktop">Find your property</span><span class="search-label-mobile">Search</span></button></form>`;
const filters=()=>`<div class="filters"><div class="pills">${[['','All projects'],['Apartment','Apartments'],['Villa','Villas'],['Townhouse','Townhouses']].map(([v,l],i)=>`<button type="button" class="pill${i===0?' active':''}" data-type-filter="${v}" aria-pressed="${i===0}">${l}</button>`).join('')}</div><span class="count" data-count aria-live="polite"></span></div>`;
const noResults=()=>`<div class="empty-state" data-empty hidden><h2>Let’s broaden your search.</h2><p>No project profiles match these filters. Change your selection or ask us about your preferred community.</p><button type="button" class="button outline" data-reset>Reset filters</button> ${link(wa('a property matching my search'),'Ask our team','button primary')}</div>`;
function faqFor(subject,kind='project') {
 if(kind==='guide') return [
 [`Where should I verify information about ${subject.toLowerCase()}?`,'Use the official source linked in this guide. Ask the relevant authority or a qualified adviser to confirm how the current requirements apply to your circumstances.'],
 ['Is this a substitute for professional advice?','No. This guide provides general information. Contracts, ownership arrangements and financing need advice specific to the transaction.'],
 ['What should I prepare before speaking to a broker?','Bring your budget, intended use, preferred timing and any existing property documents. Explain unresolved questions at the start of the discussion.'],
 ['Can Al Basel help with the next step?','Contact our team with the topic and your circumstances. We can discuss our brokerage and administrative services and identify which questions need an independent adviser.'],
 ['Are linked projects currently available?','Project profiles provide background only. Our team must confirm current units, prices, documents and availability before a property can be offered.']
 ];
 return [[`Who is the developer of ${subject.name}?`,`${subject.name} is an ${subject.developer} project. Follow the source link above for the original project information.`],[`Where is ${subject.name}?`,`${subject.name} is in ${subject.community}, Dubai. Ask for the exact building or unit location when discussing a property.`],[`Can I buy a home in ${subject.name} now?`,'Contact the brokerage to check current options. A project profile does not confirm that a particular unit is available.'],['Where can I find a current price and payment plan?','Ask for a dated unit quotation. Prices, payment schedules and handover dates need current written confirmation.'],['How do I verify a property advertisement?','Check the permit and QR code, brokerage ORN and agent BRN through official Dubai Land Department channels.']];
}
const faqHtml=(items)=>`<section class="faq"><h2>Questions, answered.</h2>${items.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</section>`;
const faqSchema=items=>({'@type':'FAQPage',mainEntity:items.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))});
async function page({route,title,description,h1,body,imageName='park-field.webp',category,schemas=[],detail=false,noindex=false}) {
 const canonical=business.url+route;
 const parts=route.split('/').filter(Boolean);
 const breadcrumb={'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:business.url+'/'},...parts.map((part,i)=>({'@type':'ListItem',position:i+2,name:i===parts.length-1?h1:part.replaceAll('-',' '),item:business.url+'/'+parts.slice(0,i+1).join('/')+'/'}))]};
 const agent={'@type':'RealEstateAgent','@id':business.url+'/#organization',name:business.name,url:business.url,telephone:business.phone,email:business.email,address:{'@type':'PostalAddress',streetAddress:'SZR, Mardoof Building 1, Office 101',addressLocality:'Dubai',addressCountry:'AE'},logo:business.url+'/assets/logo.webp',parentOrganization:{'@type':'Organization',name:business.parentOrganization},sameAs:business.socialProfiles};
 agent.identifier=[{'@type':'PropertyValue',propertyID:'Dubai Trade Licence',value:business.licence.number},{'@type':'PropertyValue',propertyID:'Dubai Chamber Membership',value:business.licence.chamberNumber},{'@type':'PropertyValue',propertyID:'DUNS',value:business.licence.duns}];
 if(business.orn)agent.identifier.push({'@type':'PropertyValue',propertyID:'RERA ORN',value:business.orn});
 agent.foundingDate='2007-04-19';
 const html=`<!doctype html><html lang="en"><head>${verificationHead}<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(title)}</title>${noindex?'<meta name="robots" content="noindex, nofollow">':''}<meta name="description" content="${esc(description)}"><link rel="canonical" href="${canonical}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="${category==='guide'?'article':'website'}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${business.url}${imageName.startsWith('/')?imageName:'/assets/'+imageName}"><meta name="theme-color" content="#ad1925"><link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png"><link rel="icon" type="image/png" sizes="64x64" href="/favicon.png"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/leads/leads.css"><script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@graph':[agent,breadcrumb,...schemas]}).replaceAll('<','\\u003c')}</script><script src="/leads/config.js" defer></script><script src="/leads/leads.js" defer></script><script src="/site.js" defer></script></head><body${detail?' class="detail-page"':''}>${header(route)}<main id="main">${body}</main>${footer(route)}</body></html>`;
 const dest=route==='/'?'dist/index.html':path.join('dist',route,'index.html');
 const enquiryPage=title.replace(/\s*\|\s*Al Basel.*$/i,'').replace(/[.]+$/,'');
 const outputHtml=html.replace(/href="(https:\/\/wa\.me\/[^\"]+)"/g,(_,href)=>{
   const target=new URL(href.replaceAll('&amp;','&'));
   const original=target.searchParams.get('text')||'';
   const interest=/(?:enquire about:?|interested in)\s*(.+?)(?:\.\s*$|\n|$)/i.exec(original)?.[1];
   target.searchParams.set('text','Hi Al Basel Real Estate. I am from the website. I need more info about '+enquiryPage+'.\nPage: '+canonical+(interest?'\nInterest: '+interest:''));
   return 'href="'+esc(target.href)+'"';
 });
 await fs.mkdir(path.dirname(dest),{recursive:true});await fs.writeFile(dest,outputHtml);
 if(!noindex)pages.push({route,title,description,h1,category:category||'information'});
}
const heading=(tag,title,desc,url,label='View all')=>`<div class="section-heading"><div><div class="eyebrow">${tag}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${url?link(url,label+' ↗','text-link'):''}</div>`;
const guideCards=(items)=>`<div class="guide-grid">${items.map(g=>`<article class="guide-card"><small>${g.category} &nbsp; / &nbsp; PROPERTY GUIDE</small><h3>${link('/guides/'+g.slug+'/',g.title)}</h3><p>${g.intro}</p>${link('/guides/'+g.slug+'/','Read the guide ↗','text-link')}</article>`).join('')}</div>`;
await page({route:'/',title:'Dubai Property, with a Personal Perspective | Al Basel',description:'Explore Dubai property projects with Al Basel Real Estate Brokers. Advice on buying, renting and managing property. Speak with our team on WhatsApp.',h1:'Find a place to call your own.',body:`<section class="hero-shell"><div class="hero">${image('park-field.webp','Park Field residences overlooking the green spaces of Dubai Hills Estate','',true)}<div class="hero-shade"></div><div class="hero-content wrap"><div class="eyebrow">DUBAI REAL ESTATE. A PERSONAL PERSPECTIVE.</div><h1>Find a place<br>to call <em>your own.</em></h1><p>A home for your next chapter. An investment in your future. Let’s find what’s right for you.</p></div><div class="hero-note">DUBAI HILLS ESTATE<br>PARK FIELD BY EMAAR</div></div></section><div class="wrap search-wrap">${search()}</div><div class="wrap reassurance"><span><b>↗</b> A member of Al Basel Group</span><span><b>◇</b> Emaar Platinum Award, 2014</span><span><b>◇</b> Deyaar Best Performance, 2014</span><span><b>⌖</b> Local knowledge. Personal advice.</span></div><section class="section wrap" id="projects">${heading('A PLACE FOR EVERY CHAPTER','Different lifestyles.<br><em>One extraordinary city.</em>','Explore the projects. Picture the possibilities.','/projects/','Explore all projects')}${filters()}${projectGrid(projects.slice(0,6))}${noResults()}${projectNotice}<div class="center all-link">${link('/projects/','Discover all projects ↗','button outline')}</div></section><section class="section soft-section"><div class="wrap">${heading('FIND YOUR NEIGHBOURHOOD','The address is just the beginning.','From green surroundings to a life by the water, find the setting that feels like you.','/communities/','Explore communities')}<div class="community-grid"><a class="community-card" href="/communities/dubai-hills-estate/">${image('park-field.webp','Parkside residences in Dubai Hills Estate')}<div class="community-caption"><h3>Dubai Hills Estate</h3><p>Green spaces. A connected way of life.</p><span class="circle-arrow">↗</span></div></a><a class="community-card" href="/projects/seagate/">${image('seagate.webp','Seagate waterfront development in Mina Rashid')}<div class="community-caption"><h3>Life by the water</h3><p>Discover Seagate at Mina Rashid.</p><span class="circle-arrow">↗</span></div></a></div><div class="related-list home-communities">${communityList.slice(0,16).map(c=>link('/communities/'+c.slug+'/',esc(c.name.replace(/\s*\(.*?\)\s*/g,' ').trim()))).join('')}${link('/communities/','All '+communityList.length+' communities ↗','text-link')}</div></div></section><section class="section wrap"><div class="editorial"><div class="editorial-image">${image('elie-saab.webp','Elie Saab villa architecture at Arabian Ranches 3')}</div><div class="editorial-copy"><div class="eyebrow">MORE THAN A PROPERTY TRANSACTION</div><h2>Good advice starts<br>with listening.</h2><p>Your reasons for moving are your own. We take the time to understand them, whether you’re buying your first Dubai home, finding a tenant or planning your next investment.</p><p>As part of ${business.parentOrganization}, we bring property sales, leasing and ownership services into one conversation.</p><div class="award-row"><div><strong>Emaar</strong>Platinum Award · 2014</div><div><strong>Deyaar</strong>Best Performance Award · 2014</div></div>${link('/about/','Get to know Al Basel ↗','text-link')}</div></div></section><section class="section soft-section"><div class="wrap">${heading('HERE FOR THE WHOLE JOURNEY','Property is personal.<br>So is our approach.','','/services/','All our services')}<div class="service-grid">${services.slice(0,3).map((s,i)=>`<a href="/services/${s.slug}/" class="service-card"><span class="number">0${i+1}</span><span class="arrow">↗</span><h3>${s.name}</h3><p>${s.description.split('. ')[0]}.</p></a>`).join('')}</div><div class="developer-strip"><p>Working with recognised names in Dubai property.</p>${link('/developers/emaar/','EMAAR','wordmark')}${link('/developers/deyaar/','deyaar','wordmark deyaar')}${link('/developers/','Meet the developers ↗','text-link')}</div></div></section><section class="section wrap">${heading('A LITTLE LOCAL KNOWLEDGE','Make your next move<br>an informed one.','','/guides/','All property guides')}${guideCards([guides[0],guides[1],guides[8]])}</section>${Object.keys(agentsBySlug).length?`<section class="section wrap">${agentShowcase(Object.values(agentsBySlug),{esc,projects})}</section>`:''}${cta()}`});
for(const [route,label,description] of [['/projects/','Explore Dubai projects','Find a setting that matches your plans. Browse project profiles, then speak to us for current, unit-specific details.'],['/off-plan/','Off-plan property in Dubai','Understand the project, developer and purchase commitment. Request current release documents before deciding on an off-plan home.'],['/buy/','Buy a property in Dubai','Start with the neighbourhood and the kind of home you want. Our team will help you check current options and the details behind them.']]) {
 await page({route,title:label+' | Al Basel',description,h1:label,body:`<div class="wrap">${crumb([[null,label]])}${intro('DISCOVER YOUR NEXT CHAPTER',label,description)}${route==='/buy/'?listingCollection(published.filter(p=>p.purpose==='buy'),business):''}${search()}<section class="section" id="projects">${filters()}${projectGrid(route==='/off-plan/'?projects.filter(p=>p.launch):projects)}${noResults()}${projectNotice}</section></div>${cta('Have a particular property in mind?')}`});
}
await page({route:'/rent/',title:'Rent a Property in Dubai | Al Basel',description:'Tell Al Basel your rental requirements in Dubai. Get help with viewings, tenancy documentation and your move-in plan.',h1:'Find your next Dubai rental.',body:`<div class="wrap">${crumb([[null,'Rent']])}${intro('A FRESH START','Find your next Dubai rental.','From your daily commute to the space you need at home, tell us what would make your next rental work for you.')}${listingCollection(published.filter(p=>p.purpose==='rent'),business,'Rentals to explore')}<div class="contact-layout"><div><h2>A brief that starts with you.</h2><p class="legal-note">Our published rental collection is being updated. Contact us for confirmed options rather than relying on an old listing.</p><div class="fact-grid"><div class="fact"><small>01</small><strong>Preferred area</strong></div><div class="fact"><small>02</small><strong>Annual budget</strong></div><div class="fact"><small>03</small><strong>Bedrooms and move-in date</strong></div><div class="fact"><small>04</small><strong>Furnished or unfurnished</strong></div></div>${link('/guides/renting-in-dubai/','Read our renting checklist ↗','text-link')}</div>${contactForm('renting a property')}</div></div>${cta('A home that fits your everyday life.')}`});
for(const p of projects) {
 const f=faqFor(p);
 await page({route:`/projects/${p.slug}/`,title:projectTitle(p),description:`Explore ${p.name} by ${p.developer} in ${p.community}, Dubai. Read project background and contact Al Basel for confirmed unit details.`,h1:p.name,imageName:p.image,detail:true,schemas:[faqSchema(f)],body:`<div class="wrap">${crumb([['/projects/','Projects'],[null,p.name]])}${intro(p.developer+' / '+p.community,p.name,p.description)}${galleryHtml(p)}<div class="detail-layout"><div class="detail-body"><section><h2>The project, at a glance.</h2>${p.launch?`<p class="notice">${p.name} developer launch profile, reviewed ${p.reviewedAt}. Emaar listed this project in its launch collection at review. Confirm current release details directly with our team.</p>`:''}<div class="fact-grid">${[['Developer',p.developer],['Community',p.community],['Home types',p.bedrooms],['Current price','Request a confirmed quotation'],['Handover','Current status to be confirmed'],['Payment plan','Request current developer terms']].map(([k,v])=>`<div class="fact"><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div><ul>${p.highlights.map(h=>`<li>${h}</li>`).join('')}</ul></section><section><h2>Before you make a shortlist.</h2><p>Ask for the exact unit reference, floor plan, orientation and ownership status at ${p.name}. The project name describes a development, while the terms of a purchase depend on the individual home.</p><p>For ${p.name}, confirm the service-charge position, existing tenancies and transaction documents. If buying off-plan here, request the registered project details and developer’s current written schedule.</p><div class="notice">Background source: ${link(p.source,p.brokerSource&&!p.source.includes('emaar.com')?'Al Basel project record':p.developer+' official project page')}${p.brochure?' · '+link(p.brochure,p.developer+' brochure (PDF)'):''}${p.floorPlan?' · '+link(p.floorPlan,'Floor plans (PDF)'):''}.${p.imageIsCommunity?' The photograph shows the wider community, not this building.':''} Reviewed ${business.reviewedAt}. Developer images may be renderings. Availability, completion and payment terms are not asserted by this page.</div></section><section><h2>Explore the setting.</h2><p>When considering ${p.name}, compare journeys from ${p.community} with your normal week. Visit the building or plot and check which surrounding facilities are operating.</p>${link('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.name+' '+p.community+' Dubai'),'View the area on Google Maps ↗','text-link')}</section>${faqHtml(f)}<section><h2>Useful next steps.</h2><div class="related-list">${p.communitySlug?link('/communities/'+p.communitySlug+'/',esc(p.community)+' guide'):''}${link('/developers/'+devSlug(p)+'/',esc(p.developer)+' projects')}${link('/guides/viewing-checklist/','Viewing checklist')}${link('/guides/buying-costs-and-fees/','Buying costs')}${link('/verification/','Licence & verification')}</div></section></div>${agentsBySlug[p.agent]?agentSidebar(p,agentsBySlug[p.agent]):sidebar(p.name)}</div></div>${cta('Could '+p.name+' be your next address?')}<div class="sticky-enquiry">${link('tel:'+business.phoneLink,'Call our team','button outline')}${link(wa(p.name),'Enquire on WhatsApp','button primary')}</div>`});
}
