await page({route:'/services/',title:'Dubai Real Estate Services | Al Basel',description:'Property sales, leasing, off-plan advice, management, holiday homes and documentation support from Al Basel Real Estate Brokers in Dubai.',h1:'Support for every stage of ownership.',body:`<div class="wrap">${crumb([[null,'Services']])}${intro('PROPERTY SERVICES','Support for every stage of ownership.','A purchase is one part of the story. Find practical support for selling, letting and looking after your Dubai property.')}<div class="service-grid">${services.map((s,i)=>`<a class="service-card" href="/services/${s.slug}/"><span class="number">${String(i+1).padStart(2,'0')}</span><span class="arrow">↗</span><h3>${s.name}</h3><p>${s.description.split('. ')[0]}.</p></a>`).join('')}</div></div>${cta()}`});
for(const s of services)await page({route:`/services/${s.slug}/`,title:`${s.name.replace('Property supervision & management','Property Management')} in Dubai | Al Basel`,description:s.description.slice(0,155),h1:s.heading,body:`<div class="wrap">${crumb([['/services/','Services'],[null,s.name]])}${intro('DUBAI / '+s.name,s.heading,s.description)}<div class="detail-layout"><div class="detail-body"><section><h2>What we can help organise.</h2><ul>${s.steps.map(step=>`<li>${step}</li>`).join('')}</ul></section><section><h2>Start with the scope.</h2><p>When you contact us about ${s.name.toLowerCase()}, explain the property, your role and the result you need. Our team will discuss the documents, parties and timing before agreeing the instruction.</p><p>For ${s.name.toLowerCase()}, request written service terms, charges and approval responsibilities. Refer legal, technical or financial questions beyond this instruction to the appropriate qualified professional.</p></section><section><h2>Plan your next conversation.</h2><p>Bring the property reference and the records you already hold. Tell us about deadlines or unresolved issues so the ${s.name.toLowerCase()} discussion addresses the decisions in front of you.</p><div class="related-list">${link('/how-we-work/','How we work')}${link('/guides/','Ownership guides')}${link('/verification/','Licence & verification')}</div></section></div>${sidebar(s.name.toLowerCase())}</div></div>`});
function contactForm(interest='buying a property') {return `<form class="contact-form" data-contact-form><h3>Tell us what you have in mind.</h3><label for="name">Your name</label><input id="name" name="name" required autocomplete="name" maxlength="100"><label for="phone">Mobile or WhatsApp number</label><input id="phone" name="phone" type="tel" required autocomplete="tel" inputmode="tel" maxlength="30"><label for="email">Email (optional)</label><input id="email" name="email" type="email" autocomplete="email" maxlength="200"><label for="interest">I’d like help with</label><select id="interest" name="interest">${['buying a property','renting a property','selling my property','off-plan projects','property management'].map(i=>`<option${i===interest?' selected':''}>${i}</option>`).join('')}</select><label for="message">A few details</label><textarea id="message" name="message" placeholder="Preferred area, budget, and when you hope to move" maxlength="2000"></textarea><button class="button primary" type="submit">Continue on WhatsApp ${icon('chat')}</button><p class="legal-note">We keep these details so our team can follow up on your enquiry, then WhatsApp opens with your message. See our <a href="/privacy/">privacy notice</a>.</p></form>`;}
await page({route:'/contact/',title:'Contact Al Basel Real Estate Brokers, Dubai',description:'Call or WhatsApp Al Basel on +971529038948. Visit SZR, Mardoof Building 1, Office 101, Dubai, or email info@albaselrealestate.ae.',h1:'Let’s talk about your next move.',body:`<div class="wrap">${crumb([[null,'Contact']])}${intro('A CONVERSATION IS A GOOD START','Let’s talk about your next move.','Buying, renting or looking after a property? Share your plans and we’ll help you work through the next steps.')}<div class="contact-layout"><div><div class="contact-detail"><small>CALL OR WHATSAPP</small>${link('tel:'+business.phoneLink,business.phone)}</div><div class="contact-detail"><small>EMAIL OUR TEAM</small>${link('mailto:'+business.email,business.email)}</div><div class="contact-detail"><small>VISIT OUR OFFICE</small><p>${esc(business.address)}</p>${link('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(business.address),'Get directions ↗','text-link')}</div><div class="contact-detail"><small>OFFICE HOURS</small><p>Pending confirmation. Please call before visiting.</p></div><p class="legal-note">For licence and advertising checks, visit our ${link('/verification/','verification page')}.</p></div>${contactForm()}</div></div>`});
